 @Test void validExplanationIsGroundedEncryptedAndSingleDebit(){consent();String k=key();var answer=send("PRIVATE_QUESTION",pet,k);assertEquals(200,answer.status(),answer.body().toString());assertEquals("INSUFFICIENT_DATA",answer.data().get("product_cards").get(0).get("fit_result").asString());assertEquals(1200,answer.data().get("product_cards").get(0).get("price_fen").asLong());assertEquals(answer.data(),send("PRIVATE_QUESTION",pet,k).data());assertEquals(1,calls.get());assertEquals(1,count("CONSUMED"));assertFalse(outgoing.contains("PRIVATE_"));assertFalse(outgoing.contains(user.toString()));assertFalse(outgoing.contains(pet.toString()));assertFalse(outgoing.contains("1200"));assertFalse(db.queryForObject("SELECT result_ciphertext FROM ai_messages WHERE id=?",String.class,UUID.fromString(answer.data().get("message_id").asString())).contains("PRIVATE_QUESTION"));assertEquals(409,send("changed",pet,k).status());assertEquals(200,read("/consumer/ai/conversations",consumer).status());assertEquals(200,read("/consumer/ai/conversations/"+conversation,consumer).status());assertEquals(200,read("/consumer/ai/quota",consumer).status());assertEquals(200,read("/consumer/ai/preferences",consumer).status());}
