 @Test void lastQuotaUnitIsReservedAtomically()throws Exception{for(int n=0;n<2;n++)assertEquals(200,send("Explain",null,key()).status());mode="WAIT";try(var pool=Executors.newSingleThreadExecutor()){var result=pool.submit(()->send("Explain",null,key()));assertTrue(entered.await(5,TimeUnit.SECONDS));assertEquals(429,send("Explain",null,key()).status());proceed.countDown();assertEquals(200,result.get().status());}assertEquals(3,count("CONSUMED"));}
 void inFlight(Runnable mutation,int expected)throws Exception{mode="WAIT";try(var pool=Executors.newSingleThreadExecutor()){var result=pool.submit(()->send("Explain",null,key()));assertTrue(entered.await(5,TimeUnit.SECONDS));mutation.run();proceed.countDown();assertEquals(expected,result.get().status());}assertEquals(0,count("CONSUMED"));assertEquals(1,count("RELEASED"));}
