 @Test void promptReleaseNeedsRbacProofEvaluationAndVersion(){assertEquals(403,read("/admin/ai/release",consumer).status());assertEquals(403,req("POST","/admin/ai/prompts/versions",Map.of("instruction","JSON"),reader,Map.of("Idempotency-Key",key())).status());assertEquals(403,req("POST","/admin/ai/prompts/versions",Map.of("instruction","JSON"),admin,Map.of("Idempotency-Key",key())).status());var p=req("POST","/admin/ai/prompts/versions",Map.of("instruction","Return JSON with verified evidence_ids"),admin,headers(false));assertEquals(200,p.status());String id=p.id();assertEquals(409,req("POST","/admin/ai/prompts/"+id+"/activate",Map.of(),admin,headers(true)).status());var evaluation=req("POST","/admin/ai/prompts/"+id+"/validate",Map.of(),admin,headers(false));assertEquals(200,evaluation.status());assertTrue(evaluation.data().get("passed").asBoolean());assertEquals(200,req("POST","/admin/ai/prompts/"+id+"/stage",Map.of("percentage",25),admin,headers(true)).status());assertEquals(200,req("POST","/admin/ai/prompts/"+id+"/activate",Map.of(),admin,headers(true)).status());assertEquals(200,req("POST","/admin/ai/prompts/55000000-0000-4000-8000-000000000002/rollback",Map.of(),admin,headers(true)).status());for(String path:List.of("release","rules","prompts","policies","evaluations"))assertEquals(200,read("/admin/ai/"+path,reader).status());assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE ai_prompt_versions SET instruction='changed' WHERE id=?",UUID.fromString(id)));assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("DELETE FROM ai_evaluations WHERE id=?",UUID.fromString(evaluation.id())));}
