 UUID purchase(String term){UUID plan=db.queryForObject("SELECT id FROM membership_plans WHERE term=? AND plan_version=1",UUID.class,term),order=UUID.randomUUID();db.update("INSERT INTO membership_orders(id,order_no,user_id,plan_id,plan_snapshot,amount_fen) SELECT ?,?,?,id,to_jsonb(p),price_fen FROM membership_plans p WHERE id=?",order,key(),user,plan);tx.executeWithoutResult(s->membership.activate(order,UUID.randomUUID()));return order;}
 @Test void purchasedMonthlyAndYearlyQuotaIsFrozenAndRenewalCannotBorrowFutureTerm(){UUID order=purchase("MONTH");var grant=db.queryForMap("SELECT * FROM ai_membership_quota_grants WHERE membership_order_id=?",order);assertEquals(20,((Number)grant.get("units")).intValue());Timestamp end=(Timestamp)grant.get("expires_at");UUID renewal=purchase("YEAR");var future=db.queryForMap("SELECT * FROM ai_membership_quota_grants WHERE membership_order_id=?",renewal);assertEquals(300,((Number)future.get("units")).intValue());assertEquals(end,future.get("starts_at"));assertEquals(20,read("/consumer/ai/quota",consumer).data().get("membership_remaining").asLong());tx.executeWithoutResult(s->membership.activate(order,UUID.randomUUID()));assertEquals(2,db.queryForObject("SELECT count(*) FROM ai_membership_quota_grants WHERE user_id=?",Integer.class,user));for(int n=0;n<4;n++)assertEquals(200,send("Explain",null,key()).status());assertEquals(19,read("/consumer/ai/quota",consumer).data().get("membership_remaining").asLong());assertEquals(1,db.queryForObject("SELECT count(*) FROM ai_quota_reservations WHERE user_id=? AND quota_bucket_id=? AND status='CONSUMED'",Integer.class,user,"MEMBER:"+order));assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE ai_membership_quota_grants SET units=99 WHERE membership_order_id=?",order));}
 @Test void expiredConversationScrubsHistoryAndDoesNotRefundConsumedCalls(){var answer=send("PRIVATE_QUESTION",null,key());assertEquals(200,answer.status());db.update("UPDATE ai_conversations SET expires_at=now()-interval '1 second' WHERE id=?",UUID.fromString(conversation));assertTrue(quotas.sweep()>0);assertEquals(404,read("/consumer/ai/conversations/"+conversation,consumer).status());assertNull(db.queryForObject("SELECT result_ciphertext FROM ai_messages WHERE id=?",String.class,UUID.fromString(answer.data().get("message_id").asString())));assertEquals(1,count("CONSUMED"));}
 @Test void revokedMembershipFencesInFlightConsumption()throws Exception{purchase("MONTH");for(int n=0;n<3;n++)assertEquals(200,send("Explain",null,key()).status());mode="WAIT";try(var pool=Executors.newSingleThreadExecutor()){var result=pool.submit(()->send("Explain",null,key()));assertTrue(entered.await(5,TimeUnit.SECONDS));db.update("UPDATE membership_subscriptions SET status='EXPIRED' WHERE user_id=?",user);proceed.countDown();assertEquals(409,result.get().status());}assertEquals(3,count("CONSUMED"));assertEquals(1,count("RELEASED"));}
 @Test void promptProofIsSingleUseAndAuditFailureRollsBack(){String token=proof();var headers=Map.of("Idempotency-Key",key(),"X-Reverify-Token",token);db.execute("CREATE FUNCTION test_ai_audit_fail() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.action='ai.prompt.create' THEN RAISE EXCEPTION 'TEST failure'; END IF; RETURN NEW; END $$");db.execute("CREATE TRIGGER test_ai_audit_fail BEFORE INSERT ON audit_event FOR EACH ROW EXECUTE FUNCTION test_ai_audit_fail()");try{assertEquals(503,req("POST","/admin/ai/prompts/versions",Map.of("instruction","JSON TEST rollback"),admin,headers).status());}finally{db.execute("DROP TRIGGER test_ai_audit_fail ON audit_event");db.execute("DROP FUNCTION test_ai_audit_fail()");}assertNull(db.queryForObject("SELECT used_at FROM reverify_grant WHERE token_hash=?",Timestamp.class,crypto.hash(token)));assertEquals(200,req("POST","/admin/ai/prompts/versions",Map.of("instruction","JSON TEST rollback"),admin,headers).status());assertEquals(403,req("POST","/admin/ai/prompts/versions",Map.of("instruction","JSON TEST second"),admin,Map.of("Idempotency-Key",key(),"X-Reverify-Token",token)).status());}
